let result = [];
let firstBlock = true;

// Split text on \n characters - FIXED: Use .item instead of .first() to get current item
let textBlocks = $('Loop Over Items1').item.json.output.split(/\n/);

for (let block of textBlocks) {
    if (block.length === 0) continue;
    result.push({
        "textSubString": block.trim(),
        "firstBlock": firstBlock
    });
    firstBlock = false;
}

return result;

// Initialize output variables
let bodyParts = [];
let images = [];

for (const item of $input.all()) {
  const block = item.json;

  if (block.type === 'paragraph') {
    const content = block.content?.trim();
    if (content) {
      bodyParts.push(content);
    }
  }

  if (block.type === 'image') {
    const imageUrl = block.image?.external?.url;
    if (imageUrl) {
      images.push(imageUrl);
    }
  }
}

return [
  {
    json: {
      body: bodyParts.join('\n'),
      images,
    },
  },
];

// Input: array of Notion format objects
const input = $input.all();

// Map and extract the fields you need
const extracted = input.map(item => ({
  id: item.json.id,
  name: item.json.name,
  platform: Array.isArray(item.json.property_platform) ? item.json.property_platform[0] : null,
  format: item.json.property_format || null
}));

// Return as individual n8n items
return extracted.map(row => ({
  json: row
}));

const articles = $input.all();

function normaliseQuery(value) {
  if (!value) return "unknown";
  return value
    .toLowerCase()
    .trim()
    .replace(/\s+/g, " ");
}

function groupBySearchQuery(data) {
  return data.reduce((groups, itemRaw) => {
    const item = itemRaw.json;

    const rawQuery = item.property_source_name || "Unknown";
    const normalisedQuery = normaliseQuery(rawQuery);

    if (!groups[normalisedQuery]) {
      groups[normalisedQuery] = {
        original_query: (rawQuery || "Unknown").toString().trim(),
        content: []
      };
    }

    // Push the ENTIRE item (all fields), plus helpful derived keys
    groups[normalisedQuery].content.push({
      ...item,
      raw_search_query: rawQuery,
      normalised_search_query: normalisedQuery,
    });

    return groups;
  }, {});
}

const groupedContent = groupBySearchQuery(articles);

// Output one n8n item per group
const outputLists = Object.entries(groupedContent).map(([normalisedQuery, group]) => ({
  json: {
    search_query: normalisedQuery,          // normalised grouping key
    display_query: group.original_query,    // original (first-seen) label
    content: group.content                  // FULL items
  }
}));

return outputLists;

